import{bQ as a,aZ as d,aL as o,u as n,G as e,I as s}from"./chunks/framework.C1gZXFVa.js";const g="/assets/010101.BnVIR_WF.png",y=JSON.parse('{"title":"业务概述","description":"用一笔「部分成交后再撤单」的现货案例，看清委托、成交、账务与行情如何串起来。","frontmatter":{"title":"业务概述","description":"用一笔「部分成交后再撤单」的现货案例，看清委托、成交、账务与行情如何串起来。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,现货手册,现货撮合,现货订单,现货结算"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/0701"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/0701"}],["meta",{"property":"og:title","content":"业务概述 · TGEX"}],["meta",{"property":"og:description","content":"用一笔「部分成交后再撤单」的现货案例，看清委托、成交、账务与行情如何串起来。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"业务概述 · TGEX"}],["meta",{"name":"twitter:description","content":"用一笔「部分成交后再撤单」的现货案例，看清委托、成交、账务与行情如何串起来。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"业务概述\\",\\"description\\":\\"用一笔「部分成交后再撤单」的现货案例，看清委托、成交、账务与行情如何串起来。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,现货手册,现货撮合,现货订单,现货结算\\",\\"url\\":\\"https://tgex.net/pages/0701\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/0701\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/0701.md","filePath":"07.现货手册/01.业务概述.md"}'),i={name:"pages/0701.md"};function l(p,t,h,T,c,b){const r=d("SpotLedger");return o(),n("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="业务概述" tabindex="-1">业务概述 <a class="header-anchor" href="#业务概述" aria-label="Permalink to &quot;业务概述&quot;">​</a></h1><p>现货是交易所中最基础、最常见的交易方式：用户用一种资产买入另一种资产，订单成交后，双方按成交结果完成资产交换。它不涉及借贷和杠杆，也没有到期结算。许多交易所的交易业务都从现货开始，合约和期权则是在此基础上扩展出的其他产品。</p><p>下面先介绍现货的基本概念，再跟随一笔买单，了解资金如何冻结、订单状态如何变化，以及这些变化会如何呈现在交易页面上。</p><h2 id="guide" tabindex="-1">本册怎么读 <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;本册怎么读 {#guide}&quot;">​</a></h2><p>建议按这条线往下读，避免在侧栏里跳着抓碎片：</p><table tabindex="0"><thead><tr><th>顺序</th><th>读什么</th><th>回答什么</th></tr></thead><tbody><tr><td>1</td><td>本页</td><td>委托 / 成交 / 账务怎么分开；统一案例数字</td></tr><tr><td>2</td><td><a href="/pages/0702">系统架构</a></td><td>谁受理、谁持热状态、谁推展示</td></tr><tr><td>3</td><td><a href="/pages/0703">交易规则</a> → <a href="/pages/0704">核心设计</a></td><td>单合不合法；账户 / 订单 / 订单簿对象</td></tr><tr><td>4</td><td>初始化四链路 → 下单 / 撮合 / 撤单 / 行情</td><td>服务怎么就绪；一笔限价单怎么跑</td></tr><tr><td>5</td><td><a href="/pages/070801">缓存总览</a></td><td>热路径权威态落在哪张内存表</td></tr></tbody></table><p><strong>本册主路径</strong>：平台撮合 · 限价单的下单、撮合、撤单、推送，以及委托查询、充提改账协同、手续费计费落地。<br><strong>明确不展开或另册</strong>：市价单细节、第三方撮合、批量撤单；链上充提细节见<a href="/pages/1003">钱包 · 核心充提流程</a>，资金语义见<a href="/pages/0601">资产与账务</a>。</p><h2 id="basics" tabindex="-1">现货是什么 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;现货是什么 {#basics}&quot;">​</a></h2><p>说白了：现货就是用一种币换另一种币，换成了就是你的。大家常听到的 BTC，可以理解成要买卖的「货」；USDT 是常见的稳定币，更像「付钱用的币」。在 <strong>BTC/USDT</strong> 这个交易对里：</p><ul><li>你要买 BTC：付 USDT，拿到 BTC</li><li>你要卖 BTC：交出 BTC，拿到 USDT</li></ul><p>一买一卖配对成功，就叫<strong>成交</strong>；两边账户里的币会按成交结果改掉。下单时系统会先把要用的币<strong>冻住</strong>，避免同一笔钱花两次；成交或撤单后再把账算清楚。</p><p>它和另外两类产品不一样：</p><ul><li><strong>合约</strong>：更关心你持了多少仓、保证金够不够，不是简单「币换币到手」</li><li><strong>期权</strong>：还要看约定条件和到期怎么算结果</li><li><strong>现货</strong>：就盯三件事——单有没有、成交了没有、账户里的币怎么变</li></ul><p>所以看现货，先把下面三个东西分开，别混在一块：</p><table tabindex="0"><thead><tr><th>看什么</th><th>人话</th></tr></thead><tbody><tr><td>委托（订单）</td><td>我还想买/卖多少？这单现在什么状态？</td></tr><tr><td>成交</td><td>到底换成了多少？按什么价格换的？</td></tr><tr><td>账务（余额）</td><td>我还能用多少？冻住了多少？币最终归谁？</td></tr></tbody></table><p>打开主流交易所的现货交易页，通常会看到这些信息:</p><table tabindex="0"><thead><tr><th>页面上</th><th>你在看什么</th></tr></thead><tbody><tr><td>交易对</td><td>这一页买卖的是哪两种币，比如 BTC/USDT</td></tr><tr><td>盘口</td><td>市场上大家挂着的买卖价和量（不一定是你的单）</td></tr><tr><td>当前委托</td><td><strong>你自己</strong>还没做完的单</td></tr><tr><td>成交记录</td><td>已经换成事实的记录：价格、数量、时间</td></tr><tr><td>余额</td><td>你账户里可用多少、冻住多少</td></tr><tr><td>K 线</td><td>最近一段时间价格大概怎么走</td></tr></tbody></table><p>记住两个常见容易混的点：</p><ol><li><strong>盘口</strong>是市场意愿；<strong>当前委托</strong>才是你的单。</li><li><strong>盘口里的量</strong>还没换完；<strong>成交记录</strong>里的才是已经换成的。</li></ol><p>光记名字还不够。下面就在 <strong>BTC/USDT</strong> 上跟一笔买单：看<strong>委托</strong>怎么从下单变成部分成交再撤掉剩余，<strong>成交</strong>发生了哪一截，<strong>账务</strong>里可用 / 冻结怎么变，以及页面上的当前委托、成交记录、盘口大致会怎样。</p><h2 id="complete" tabindex="-1">一笔交易案例 <a class="header-anchor" href="#complete" aria-label="Permalink to &quot;一笔交易案例 {#complete}&quot;">​</a></h2><p>接着上面的三个对象来看。后文现货章节也沿用同一组数，避免每页换例子：</p><blockquote><p>限价买入 <strong>0.01 BTC</strong>，先成交 <strong>0.006 BTC</strong>，再撤掉剩下的 <strong>0.004 BTC</strong>。</p></blockquote><p>整笔单可以想成这条线（先看结果，系统内部怎么接力，见后面的主流程）：</p><p align="center" class="spot-flow-figure"><img src="'+g+'" alt="一笔交易案例业务顺序"></p><p>假设你是用户 A，账户里有 <strong>1,000 USDT</strong>，想按 <strong>60,000 USDT</strong> 的限价买 <strong>0.01 BTC</strong>（大约要准备 600 USDT）。市场上卖方暂时只愿意卖给你 <strong>0.006 BTC</strong>，买不完的部分你再撤单。先不算手续费，并假定成交价就等于你的限价。</p><p>对照上一节：表里的「订单」列就是<strong>委托</strong>；「新增 BTC / 支出」对应<strong>成交</strong>；「可用 / 冻结」就是<strong>账务</strong>；最后一列是页面上大概会看到的变化。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">A 可用 USDT</th><th style="text-align:right;">A 冻结 USDT</th><th style="text-align:right;">A 新增 BTC</th><th>订单（委托）</th><th>页面上大致怎样</th></tr></thead><tbody><tr><td>初始</td><td style="text-align:right;">1,000</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>还没有单</td><td>余额里能用 1,000 USDT</td></tr><tr><td>下单占用 600</td><td style="text-align:right;">400</td><td style="text-align:right;">600</td><td style="text-align:right;">0</td><td>未成交</td><td><strong>当前委托</strong>出现这单；<strong>盘口</strong>这档买量增加</td></tr><tr><td>成交 0.006 BTC</td><td style="text-align:right;">400</td><td style="text-align:right;">240</td><td style="text-align:right;">0.006</td><td>部分成交</td><td><strong>成交记录</strong>多一笔；盘口买量减少；余额里多了 BTC、冻结变少</td></tr><tr><td>撤销剩余 0.004 BTC</td><td style="text-align:right;">640</td><td style="text-align:right;">0</td><td style="text-align:right;">0.006</td><td>已撤销</td><td>当前委托去掉剩余；盘口再减掉没成交的那截买量</td></tr></tbody></table><p>读表时可以按上一节的口诀核对：</p><ol><li><strong>委托</strong>：有没有单、还剩多少、最后是部分成交后撤掉</li><li><strong>成交</strong>：真正换成的是 0.006 BTC，花掉约 360 USDT；撤单<strong>不会</strong>把这笔成交取消</li><li><strong>账务</strong>：下单先冻 600 → 成交后冻结降到 240 → 撤单后冻结清零，可用回到 640</li></ol><p>资金每一步怎么算，可在下方演算里拖着看。</p>',32)),s(r),t[1]||(t[1]=e('<p>成交、撤单之后，<strong>成交记录</strong>和<strong>盘口</strong>还会再刷一刷，那是行情在推展示，并不另改你的订单和余额对错。推送细节见<a href="/pages/070509">行情推送流程</a>。系统里网关、委托、撮合怎么交接，见<a href="/pages/070502">下单主流程</a>、<a href="/pages/070508">撮合主流程</a>、<a href="/pages/070503">撤单主流程</a>；超时后怎么查单见<a href="/pages/070510">委托查询主流程</a>。</p><h3 id="卖单对称理解" tabindex="-1">卖单对称理解 <a class="header-anchor" href="#卖单对称理解" aria-label="Permalink to &quot;卖单对称理解&quot;">​</a></h3><p>同一组数字从卖方看：用户 B 卖出 0.01 BTC，先成交 0.006，再撤剩余 0.004。下单时冻结 0.01 BTC；成交后减少 0.006 BTC 占用并增加 360 USDT；撤单后解冻剩余 0.004 BTC。买卖共用同一笔成交，只是资产方向相反。</p><h3 id="手续费与优价成交" tabindex="-1">手续费与优价成交 <a class="header-anchor" href="#手续费与优价成交" aria-label="Permalink to &quot;手续费与优价成交&quot;">​</a></h3><table tabindex="0"><thead><tr><th>扩展</th><th>教学处理</th></tr></thead><tbody><tr><td>假设 taker 0.1% 从获得币扣除</td><td>买方净得 BTC 略少于 0.006；账务需单独记费用流水</td></tr><tr><td>成交价优于买入限价</td><td>实际扣款小于原预占；多占用部分须在结算或撤单路径中释放并可解释</td></tr></tbody></table><p>真实费率与扣费币种以产品配置为准；上表只用于演算。工程上成交时如何取费率、扣费、写入手续费暂存，见<a href="/pages/070512">手续费计费落地</a>。</p><p>同组：<a href="/pages/0702">系统架构</a> · <a href="/pages/0703">交易规则</a> · <a href="/pages/0704">核心设计</a> · <a href="/pages/070502">下单主流程</a></p>',7))])}const _=a(i,[["render",l]]);export{y as __pageData,_ as default};
